CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_finish(p_operation_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare op private.dic_admin_account_delete_operations; removed integer:=0; community_ids uuid[]:='{}'::uuid[];
begin
 select * into op from private.dic_admin_account_delete_operations where id=p_operation_id for update;
 if not found or op.actor_id is distinct from p_actor_id then
  raise exception using errcode='42501',message='Deletion operation unavailable.';
 end if;
 if op.phase='completed' then
  return jsonb_build_object('ok',true,'completed',true,'community_removed',op.community_removed,'retry',true);
 end if;
 if op.phase<>'prepared' then raise exception using errcode='23514',message='Deletion was not prepared.'; end if;
 -- Never trust an edge-reported success alone. The DB verifies Auth is gone.
 if exists(select 1 from auth.users where id=op.target_id) then
  raise exception using errcode='23514',message='Auth account still exists.';
 end if;
 if op.community_mode='remove' then
  -- Capture IDs BEFORE removing their private association; only this member's
  -- immutable contributor IDs may be selected, including detached old shots.
  select coalesce(array_agg(cl.community_shot_id order by cl.community_shot_id),'{}'::uuid[])
    into community_ids from private.contribution_links cl
    where cl.contributor_id=any(op.contributor_ids);
  -- Keep private review audit records but remove public references to purged shots.
  update public.admin_reviews set community_shot_id=null
    where community_shot_id=any(community_ids);
  delete from private.contribution_links where community_shot_id=any(community_ids)
    and contributor_id=any(op.contributor_ids);
  delete from public.community_shots where id=any(community_ids);
  get diagnostics removed=row_count;
  -- Contributor tokens for removed data have no future weighting role.
  delete from private.contributors c where c.id=any(op.contributor_ids)
    and c.owner_id is null and not exists(
      select 1 from private.contribution_links cl where cl.contributor_id=c.id);
 end if;
 update private.dic_admin_account_delete_operations
  set phase='completed',community_removed=removed,completed_at=now(),
      expected_impact=expected_impact-'email'-'member_id',
      contributor_ids='{}'::uuid[] where id=op.id;
 return jsonb_build_object('ok',true,'completed',true,'community_removed',removed);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_prepare(p_operation_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare op private.dic_admin_account_delete_operations; ids uuid[]; actual jsonb; storage_blocked boolean:=false;
begin
 select * into op from private.dic_admin_account_delete_operations
 where id=p_operation_id for update;
 if not found or op.actor_id is distinct from p_actor_id then
  raise exception using errcode='42501',message='Deletion operation unavailable.';
 end if;
 if op.phase='completed' then return jsonb_build_object('ok',true,'completed',true); end if;
 if not exists(select 1 from private.app_admins where owner_id=p_actor_id)
    or not exists(select 1 from private.beta_members
       where owner_id=p_actor_id and enabled and admitted_at is not null) then
  raise exception using errcode='42501',message='Administrator no longer admitted.';
 end if;
 if exists(select 1 from private.app_admins where owner_id=op.target_id)
    or op.target_id=p_actor_id then
  raise exception using errcode='42501',message='Administrator accounts are protected.';
 end if;
 if op.phase='requested' then
  if not exists(select 1 from auth.users where id=op.target_id) then
   raise exception using errcode='23514',message='Target account is missing before preparation.';
  end if;
  -- Recheck the same preview under the service-side record lock.
  -- No JWT actor impersonation or unsafe service-role bypass of an admin check.
  actual:=private.dic_admin_account_delete_impact(op.target_id);
  if actual is distinct from op.expected_impact then
   raise exception using errcode='PT409',message='Account changed after confirmation.';
  end if;
  select coalesce(array_agg(c.id order by c.id),'{}'::uuid[]) into ids
  from private.contributors c where c.owner_id=op.target_id;
  -- Supabase Auth deletion refuses users who own Storage objects. Fail before
  -- changing admission when the live provider exposes that table.
  if to_regclass('storage.objects') is not null then
   execute 'select exists(select 1 from storage.objects where owner=$1 or owner_id=$1::text)'
     into storage_blocked using op.target_id;
   if storage_blocked then
    raise exception using errcode='23514',message='Member has Storage-owned objects; review before deletion.';
   end if;
  end if;
  -- Prevent deletion of prior actor audit evidence if a formerly privileged user
  -- was subsequently demoted. Do not silently erase immutable admin audits.
  if exists(select 1 from private.admin_content_edits where actor_id=op.target_id) then
   raise exception using errcode='23514',message='Historical administrative actor audit requires separate review.';
  end if;
  update private.beta_members set enabled=false where owner_id=op.target_id;
  -- Eliminate restrictive user references; retain minimum action/timestamp audit.
  update private.admin_content_edits
     set subject_owner_id=null,before_values='{}'::jsonb,after_values='{}'::jsonb
     where subject_owner_id=op.target_id;
  delete from private.dic_source_attempts where owner_id=op.target_id;
  update private.import_control
     set owner_only_exception_owner_id=null,owner_only_exception_approved_at=null,
         owner_only_exception_expires_at=null
     where owner_only_exception_owner_id=op.target_id;
  update private.dic_admin_account_delete_operations
     set phase='prepared',contributor_ids=ids,prepared_at=now()
     where id=op.id;
  op.phase:='prepared';op.contributor_ids:=ids;
 end if;
 if op.phase='prepared' and exists(
  select 1 from private.beta_members where owner_id=op.target_id and enabled
 ) then
  raise exception using errcode='23514',message='Admission unexpectedly restored while deleting.';
 end if;
 return jsonb_build_object('ok',true,'target_id',op.target_id,'mode',op.community_mode,'phase',op.phase);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_request(p_member_id uuid, p_community_mode text, p_expected_impact jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); actual jsonb; prior private.dic_admin_account_delete_operations; opid uuid;
begin
 perform private.require_member();
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator required.';
 end if;
 if p_community_mode not in ('keep','remove') or p_community_mode is null
    or p_expected_impact is null or p_member_id is null then
  raise exception using errcode='22023',message='Invalid account deletion confirmation.';
 end if;
 if p_member_id=actor or exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator accounts are protected.';
 end if;
 select * into prior from private.dic_admin_account_delete_operations
 where target_id=p_member_id and phase<>'completed' for update;
 if found then
  if prior.actor_id is distinct from actor or prior.community_mode<>p_community_mode then
   raise exception using errcode='23514',message='Another deletion is already in progress.';
  end if;
  return jsonb_build_object('ok',true,'operation_id',prior.id,'phase',prior.phase,'retry',true);
 end if;
 perform 1 from auth.users where id=p_member_id for update;
 actual:=private.dic_admin_account_delete_preview(p_member_id);
 if actual is distinct from p_expected_impact then
  raise exception using errcode='PT409',message='Account records changed. Review deletion impact again.';
 end if;
 insert into private.dic_admin_account_delete_operations(actor_id,target_id,community_mode,expected_impact)
 values(actor,p_member_id,p_community_mode,actual) returning id into opid;
 return jsonb_build_object('ok',true,'operation_id',opid,'phase','requested');
end $function$

CREATE OR REPLACE FUNCTION private.dic_edit_my_coffee(p_library_entry uuid, p_expected_revision bigint, p_details jsonb, p_source_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 u uuid:=private.require_member();
 lib public.library_entries; sub public.coffee_submissions; canonical public.coffees;
 clean jsonb; k text; value text; name_text text; roaster_text text; url_text text;
 updated_id uuid;
begin
 if p_library_entry is null or p_expected_revision is null or p_expected_revision<1 or
    jsonb_typeof(p_details) is distinct from 'object' or octet_length(p_details::text)>8000 then
   raise exception using errcode='22023',message='Invalid coffee edit request.';
 end if;
 for k in select jsonb_object_keys(p_details) loop
  if k not in ('name','roaster','release_label','origin','roast_level',
      'elevation_m','process','is_decaf','decaffeination_method','variety','producer','tasting_notes') then
   raise exception using errcode='22023',message='Unsupported coffee detail.';
  end if;
  if k='is_decaf' then
   if jsonb_typeof(p_details->k) is distinct from 'boolean' then
    raise exception using errcode='22023',message='Decaf flag must be a boolean.';
   end if;
  else
   if jsonb_typeof(p_details->k) not in ('null','string') then
    raise exception using errcode='22023',message='Coffee details must be text.';
   end if;
   value:=nullif(btrim(p_details->>k),'');
   if length(value)>(case when k='tasting_notes' then 2000 else 300 end) then
    raise exception using errcode='22023',message='Coffee detail is too long.';
   end if;
  end if;
 end loop;
 name_text:=nullif(btrim(p_details->>'name'),'');
 roaster_text:=nullif(btrim(p_details->>'roaster'),'');
 if name_text is null or length(name_text)>200 or roaster_text is null or length(roaster_text)>200 then
  raise exception using errcode='22023',message='Coffee name and roaster are required.';
 end if;
 if nullif(btrim(p_details->>'roast_level'),'') is not null
   and p_details->>'roast_level' not in
      ('Ultra Light','Very Light','Light','Medium-Light','Medium','Medium-Dark','Dark') then
  raise exception using errcode='22023',message='Choose a recognized roast level.';
 end if;
 if p_details ? 'decaffeination_method' and
    nullif(btrim(p_details->>'decaffeination_method'),'') is not null and
    p_details->>'decaffeination_method' not in ('Water Process','Sugar Process','Carbon Dioxide (CO2)') then
   raise exception using errcode='22023',message='Unknown decaffeination method.';
 end if;
 if p_details ? 'is_decaf' and p_details->>'is_decaf'='true' and
    name_text ~* '(^|[^[:alnum:]])(half[ -]?caf|semi[ -]?decaf|partially[ -]?decaf)' then
   raise exception using errcode='22023',message='Half-caf cannot be marked fully decaf.';
 end if;
 url_text:=nullif(btrim(p_source_url),'');
 if url_text is not null and (length(url_text)>4000 or url_text !~ '^https://[^[:space:]/?#]+') then
   raise exception using errcode='22023',message='Source URL must be HTTPS.';
 end if;
 clean:=jsonb_build_object(
  'name',name_text,'roaster',roaster_text,
  'release_label',nullif(btrim(p_details->>'release_label'),''),
  'origin',nullif(btrim(p_details->>'origin'),''),
  'roast_level',nullif(btrim(p_details->>'roast_level'),''),
  'elevation_m',nullif(btrim(p_details->>'elevation_m'),''),
  'process',nullif(btrim(p_details->>'process'),''),
  'variety',nullif(btrim(p_details->>'variety'),''),
  'producer',nullif(btrim(p_details->>'producer'),''),
  'tasting_notes',nullif(btrim(p_details->>'tasting_notes'),'')
 );
 -- New fields are additive. Older clients that omit them preserve previously
 -- submitted details. Explicit False removes a stale decaf method.
 if p_details ? 'is_decaf' or p_details ? 'decaffeination_method' then
  clean:=clean||jsonb_build_object(
   'is_decaf',coalesce((p_details->>'is_decaf')::boolean,
      name_text ~* '(^|[^[:alnum:]])decaf(feinated)?([^[:alnum:]]|$)')
      and name_text !~* '(^|[^[:alnum:]])(half[ -]?caf|semi[ -]?decaf|partially[ -]?decaf)',
   'decaffeination_method',case when
     coalesce((p_details->>'is_decaf')::boolean,
      name_text ~* '(^|[^[:alnum:]])decaf(feinated)?([^[:alnum:]]|$)')
      and name_text !~* '(^|[^[:alnum:]])(half[ -]?caf|semi[ -]?decaf|partially[ -]?decaf)'
     then nullif(btrim(p_details->>'decaffeination_method'),'') else null end
  );
 end if;
 select * into lib from public.library_entries
    where id=p_library_entry and owner_id=u and hidden_at is null for update;
 if lib.id is null then raise exception using errcode='42501',message='Coffee is not in your library.';end if;

 if lib.coffee_id is null then
  select * into sub from public.coffee_submissions
    where id=lib.submission_id and owner_id=u for update;
  if sub.id is null or sub.status<>'pending' then
   raise exception using errcode='23514',message='This submission is no longer editable.';
  end if;
  if sub.revision<>p_expected_revision then
   return jsonb_build_object('ok',false,'code','conflict','revision',sub.revision);
  end if;
  update public.coffee_submissions
  set proposed_data=(sub.proposed_data || clean),source_url=url_text
  where id=sub.id returning id into updated_id;
  return jsonb_build_object('ok',true,'kind','updated_pending','submission_id',updated_id);
 end if;

 select * into canonical from public.coffees
   where id=lib.coffee_id and verification_state='verified' for share;
 if canonical.id is null then
  raise exception using errcode='23514',message='The verified coffee is unavailable.';
 end if;
 -- Reuse a still-pending correction to avoid duplicate queue entries. Editing a
 -- correction never changes the verified source or this member's shot history.
 select * into sub from public.coffee_submissions
 where owner_id=u and canonical_coffee_id=canonical.id and status='pending'
 order by updated_at desc,id desc limit 1 for update;
 if sub.id is not null then
  if p_expected_revision<>sub.revision then
   return jsonb_build_object('ok',false,'code','conflict','revision',sub.revision);
  end if;
  -- Old clients omit both additive keys. Preserve previously submitted
  -- decaf details when updating an existing canonical correction too.
  if not (p_details ? 'is_decaf' or p_details ? 'decaffeination_method') then
   clean:=clean||(select coalesce(jsonb_object_agg(e.key,e.value),'{}'::jsonb)
    from jsonb_each(sub.proposed_data) e
    where e.key in ('is_decaf','decaffeination_method'));
  end if;
  update public.coffee_submissions set proposed_data=clean,source_url=url_text,
   base_coffee_revision=canonical.revision where id=sub.id returning id into updated_id;
 else
  if p_expected_revision<>canonical.revision then
   return jsonb_build_object('ok',false,'code','conflict','revision',canonical.revision);
  end if;
  insert into public.coffee_submissions(
    owner_id,canonical_coffee_id,base_coffee_revision,proposed_data,source_url,status
  ) values(u,canonical.id,canonical.revision,clean,url_text,'pending')
  returning id into updated_id;
 end if;
 return jsonb_build_object('ok',true,'kind','correction_requested','submission_id',updated_id);
end $function$

CREATE OR REPLACE FUNCTION public.dic_source_check_target(submission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.coffee_submissions; host text; cname text;
begin
 if coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role',
             nullif(current_setting('request.jwt.claim.role',true),'')) is distinct from 'service_role' then
  raise exception using errcode='42501',message='Trusted source worker required.';
 end if;
 select * into s from public.coffee_submissions
 where id=submission_id and status in ('pending','conflict');
 if not found then return null; end if;
 if not exists(select 1 from private.beta_members where owner_id=s.owner_id and enabled) then
  return null;
 end if;
 select proof->>'official_domain',proof->>'canonical_name'
 into host,cname
 from (select private.dic_verified_roaster_page_proof(s.proposed_data->>'roaster') as proof) p;
 if host is null or s.source_url is null then return null; end if;
 return jsonb_build_object('submission_id',s.id,'submission_revision',s.revision,'source_url',s.source_url,
  'official_host',host,'roaster',cname,'name',s.proposed_data->>'name',
  'release_label',s.proposed_data->>'release_label',
  'origin',s.proposed_data->>'origin','process',s.proposed_data->>'process','producer',s.proposed_data->>'producer');
end $function$

CREATE OR REPLACE FUNCTION public.dic_source_claim(submission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid; existing private.dic_source_attempts; total_24h integer;
begin
 if coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role',
             nullif(current_setting('request.jwt.claim.role',true),'')) is distinct from 'service_role' then
  raise exception using errcode='42501',message='Trusted worker required.';
 end if;
 select owner_id into actor from public.coffee_submissions
 where id=submission_id and status in ('pending','conflict');
 if actor is null then return jsonb_build_object('allowed',false,'reason','not_pending');end if;
 -- Share lock keeps admission stable for this atomic budget claim.
 perform 1 from private.beta_members where owner_id=actor and enabled for share;
 if not found then return jsonb_build_object('allowed',false,'reason','not_admitted');end if;
 perform pg_advisory_xact_lock(hashtextextended(actor::text,9470));
 select attempts.* into existing from private.dic_source_attempts as attempts
 where attempts.submission_id=dic_source_claim.submission_id for update;
 select coalesce(sum(attempts),0) into total_24h from private.dic_source_attempts
 where owner_id=actor and window_started_at>now()-interval '24 hours';
 if total_24h>=30 then return jsonb_build_object('allowed',false,'reason','account_budget');end if;
 if existing.submission_id is not null
  and existing.window_started_at>now()-interval '24 hours'
  and (existing.attempts>=6 or existing.started_at>now()-interval '15 minutes') then
  return jsonb_build_object('allowed',false,'reason','retry_later');
 end if;
 insert into private.dic_source_attempts(submission_id,owner_id,started_at,window_started_at,attempts)
 values(dic_source_claim.submission_id,actor,now(),now(),1)
 on conflict on constraint dic_source_attempts_pkey do update set
  started_at=now(),
  window_started_at=case when private.dic_source_attempts.window_started_at<=now()-interval '24 hours'
   then now() else private.dic_source_attempts.window_started_at end,
  attempts=case when private.dic_source_attempts.window_started_at<=now()-interval '24 hours'
   then 1 else private.dic_source_attempts.attempts+1 end;
 return jsonb_build_object('allowed',true);
end $function$
